// Teslim hedefi EN-AZ-BİR-KEZ: backend, gönderim sonrası çökmede aynı olayı
// yeniden yollar. Tekilleştirme alıcı tarafın işidir ve anahtar `event_id`'dir
// (backend sözleşmesi: kimlik yeniden gönderimlerde DEĞİŞMEZ).
//
// Pencere sınırlıdır (son 500 kimlik): kalıcı bir depo tutmak bu workflow'un
// işi değil, sınırsız büyüyen bir static data ise kendi başına bir arıza olur.
const state = $getWorkflowStaticData('global');
if (!Array.isArray(state.seenEventIds)) state.seenEventIds = [];

const body = $input.first().json.body || {};
const eventId = body.event_id;

if (!eventId) {
  // Kimliksiz zarf sözleşme dışıdır — sessizce geçirmek yerine görünür kıl.
  return [{ json: { duplicate: false, malformed: true, envelope: body } }];
}

if (state.seenEventIds.includes(eventId)) {
  return [{ json: { duplicate: true, event_id: eventId } }];
}

state.seenEventIds.push(eventId);
if (state.seenEventIds.length > 500) {
  state.seenEventIds = state.seenEventIds.slice(-500);
}

return [{ json: { duplicate: false, malformed: false, envelope: body, event_id: eventId } }];

// Zarf sözleşmesi (backend: services/notifications.py::build_envelope):
//   { event_id, kind, payload, contract_version }
// `contract_version` alan eklendiğinde/çıktığında artar — mesajda görünür
// olması, canlıda sürüm uyuşmazlığını sessiz bırakmamak içindir.
const item = $input.first().json;

if (item.malformed) {
  return [{ json: { message: '⚠️ Sektör paketi: KİMLİKSİZ olay zarfı geldi (sözleşme dışı). Ham gövde loglarda.' } }];
}

const envelope = item.envelope || {};
const payload = envelope.payload || {};

const BASLIK = {
  'package_event.stale_assignment_fallback': '🟠 Bayat atama — paketsiz yola düşüldü',
  'package_event.package_read_error': '🔴 Paket okunamadı — paketsiz yola düşüldü',
  'package_event.mismatch_fallthrough': '🟡 Özel gün eşleşmedi — genel içerik üretildi'
};

const baslik = BASLIK[envelope.kind] || `ℹ️ ${envelope.kind}`;
const detay = payload.detail ? JSON.stringify(payload.detail) : '—';

const message = [
  baslik,
  '',
  `Marka: ${payload.brand_id || '—'}`,
  `Sektör: ${payload.sector_id || '—'}`,
  `Paket: ${payload.package_id || '—'}`,
  `Detay: ${detay}`,
  '',
  `Olay: ${envelope.event_id} (sözleşme v${envelope.contract_version})`
].join('\n');

return [{ json: { message } }];
